        Scanner sc = new Scanner(System.in);

        String type = sc.nextLine();

        Animal a;

        if (type.equals("Cat")) {
            a = new Cat();
        } else {
            a = new Dog();
        }

        Dog d = (Dog) a;
        d.bark();

        sc.close();
    }
}

